ALTER TABLE "user_preferences" ADD CONSTRAINT "user_preferences_avatar_tone_check" CHECK ("user_preferences"."avatar_tone" is null or ("user_preferences"."avatar_tone" >= 0 and "user_preferences"."avatar_tone" <= 5));